function extract($, ctx) {
  const items = [];
  const seen = new Set();

  $('script[type="application/ld+json"]').each(function () {
    let data;
    try {
      data = JSON.parse($(this).text());
    } catch (e) {
      return;
    }

    // Helper to find a Menu object in various possible shapes
    function getMenu(obj) {
      if (!obj) return null;
      if (obj['@type'] === 'Menu') return obj;
      if (Array.isArray(obj)) {
        for (var i = 0; i < obj.length; i++) {
          if (obj[i] && obj[i]['@type'] === 'Menu') return obj[i];
        }
      }
      if (obj['@graph']) {
        for (var i = 0; i < obj['@graph'].length; i++) {
          if (obj['@graph'][i] && obj['@graph'][i]['@type'] === 'Menu')
            return obj['@graph'][i];
        }
      }
      return null;
    }

    var menu = getMenu(data);
    if (!menu) return;

    var sections = menu.hasMenuSection || [];
    for (var s = 0; s < sections.length; s++) {
      var sec = sections[s];
      var sectionName = sec.name ? cleanText(sec.name) : null;
      var menuItems = sec.hasMenuItem || [];
      for (var i = 0; i < menuItems.length; i++) {
        var it = menuItems[i];
        var name = it.name ? cleanText(it.name) : null;
        if (!name) continue;
        var description = it.description ? cleanText(it.description) : null;
        var price = null;
        if (it.offers) {
          var offer = it.offers;
          var priceVal = null;
          if (Array.isArray(offer)) {
            for (var o = 0; o < offer.length; o++) {
              if (offer[o] && offer[o].price !== undefined) {
                priceVal = offer[o].price;
                break;
              }
            }
          } else {
            priceVal = offer.price !== undefined ? offer.price : null;
          }
          if (priceVal !== null) price = parsePrice(String(priceVal));
        }
        var key = (sectionName || '') + '||' + name + '||' + (price || '');
        if (!seen.has(key)) {
          seen.add(key);
          items.push({ section: sectionName, name: name, description: description, price: price });
        }
      }
    }
  });

  return items;
}
